t.script:
                document.addEventListener("DOMContentLoaded", function () {
                    const csrf_token = "";

                    document.addEventListener("click", function (e) {
                        const approveBtn = e.target.closest(".approved-timesheet-btn");
                        const rejectBtn = e.target.closest(".rejected-timesheet-btn");
                        const approveCorr = e.target.closest(".approved-correction-btn");
                        const rejectCorr = e.target.closest(".rejected-correction-btn");

                        if (approveBtn || rejectBtn || approveCorr || rejectCorr) {
                            e.stopPropagation(); // biar gak ikut klik
                        }

                        // APPROVE
                        if (approveBtn) {
                            const timesheetId = approveBtn.dataset.timesheetId;
                            console.log("Approve timesheet", timesheetId);

                            fetch(`/portal/timesheets/${timesheetId}?model=account.analytic.line&function=approved`, {
                                method: "POST",
                                headers: { "Content-Type": "application/x-www-form-urlencoded" },
                                body: `csrf_token=${csrf_token}`
                            })
                            .then(res => res.json())
                            .then(data => {
                                console.log("Response approve:", data);
                                if (data.success) {
                                    approveBtn.closest("tr").remove();
                                } else {
                                    alert("Failed: " + (data.error || "unknown error"));
                                }
                            })
                            .catch(err => console.error("Approval error:", err));
                            return;
                        }

                        // REJECT
                        if (rejectBtn) {
                            const timesheetId = rejectBtn.dataset.timesheetId;
                            console.log("Reject timesheet", timesheetId);

                            fetch(`/portal/timesheets/${timesheetId}?model=account.analytic.line&function=rejected`, {
                                method: "POST",
                                headers: { "Content-Type": "application/x-www-form-urlencoded" },
                                body: `csrf_token=${csrf_token}`
                            })
                            .then(res => res.json())
                            .then(data => {
                                console.log("Response reject:", data);
                                if (data.success) {
                                    rejectBtn.closest("tr").remove();
                                } else {
                                    alert("Failed: " + (data.error || "unknown error"));
                                }
                            })
                            .catch(err => console.error("Rejection error:", err));
                            return;
                        }

                        // APPROVE correction
                        if (approveCorr) {
                            const correctionId = approveCorr.dataset.correctionId;
                            fetch(`/portal/timesheets/corrections/${correctionId}?model=account.analytic.line.request&function=approved`, {
                                method: "POST",
                                headers: { "Content-Type": "application/x-www-form-urlencoded" },
                                body: `csrf_token=${csrf_token}`
                            })
                            .then(res => res.json())
                            .then(data => {
                                if (data.success) approveCorr.closest("tr").remove();
                                else alert("Failed: " + (data.error || "unknown error"));
                            })
                            .catch(err => console.error("Approval error:", err));
                            return;
                        }

                        // REJECT correction
                        if (rejectCorr) {
                            const correctionId = rejectCorr.dataset.correctionId;
                            fetch(`/portal/timesheets/corrections/${correctionId}?model=account.analytic.line.request&function=rejected`, {
                                method: "POST",
                                headers: { "Content-Type": "application/x-www-form-urlencoded" },
                                body: `csrf_token=${csrf_token}`
                            })
                            .then(res => res.json())
                            .then(data => {
                                if (data.success) rejectCorr.closest("tr").remove();
                                else alert("Failed: " + (data.error || "unknown error"));
                            })
                            .catch(err => console.error("Rejection error:", err));
                            return;
                        }
                    });
                });

                // approved timesheet
                document.addEventListener("DOMContentLoaded", function () {
                    const approveForm = document.getElementById("form_approve_timesheet");
                    const approveButton = document.getElementById("btn_approve_timesheet");
                    const csrfToken = approveForm.querySelector("input[name='csrf_token']").value;
                    approveForm.addEventListener("submit", function (e) {
                        e.preventDefault();
                        approveButton.disabled = true;
                        approveButton.textContent = "Processing...";
                        fetch(approveForm.action, {
                            method: "POST",
                            headers: {
                                "Content-Type": "application/x-www-form-urlencoded",
                            },
                            body: `csrf_token=${csrfToken}`
                        })
                        .then(res => res.json())
                        .then(data => {
                            approveButton.disabled = false;
                            if (data.success) {
                                window.location.reload();
                                alert("Timesheet has been approved successfully!");
                            } else {
                                window.location.reload();
                                alert(data.error || "Failed to approve timesheet.");
                            }
                        })
                        .catch(err => {
                            console.error("Error approving timesheet:", err);
                        });
                    });
                });

                // rejected timesheet
                document.addEventListener("DOMContentLoaded", function () {
                    const approveForm = document.getElementById("form_rejected_timesheet");
                    const approveButton = document.getElementById("btn_rejected_timesheet");
                    const csrfToken = approveForm.querySelector("input[name='csrf_token']").value;
                    approveForm.addEventListener("submit", function (e) {
                        e.preventDefault();
                        approveButton.disabled = true;
                        approveButton.textContent = "Processing...";
                        fetch(approveForm.action, {
                            method: "POST",
                            headers: {
                                "Content-Type": "application/x-www-form-urlencoded",
                            },
                            body: `csrf_token=${csrfToken}`
                        })
                        .then(res => res.json())
                        .then(data => {
                            approveButton.disabled = false;
                            if (data.success) {
                                window.location.reload();
                                alert("Timesheet has been rejected successfully!");
                            } else {
                                window.location.reload();
                                alert(data.error || "Failed to rejected timesheet.");
                            }
                        })
                        .catch(err => {
                            console.error("Error rejecting timesheet:", err);
                        });
                    });
                });

                // handle Approved - Rejected Line
                document.addEventListener("DOMContentLoaded", function () {
                    const csrfToken = "";
                    document.addEventListener("click", async function (e) {
                        const approveBtn = e.target.closest(".approved-correction-form-btn");
                        const rejectBtn = e.target.closest(".rejected-correction-form-btn");
                        if (!approveBtn && !rejectBtn) return;
                        const btn = approveBtn || rejectBtn;
                        if (btn) {
                            const correctionId = btn.dataset.correctionId;
                            const actionType = approveBtn ? "approved" : "rejected";
                            const row = btn.closest("tr");
                            btn.disabled = true;
                            btn.innerHTML = ` Processing...`;
                            fetch(`/portal/timesheets/corrections/${correctionId}?model=account.analytic.line.request&function=${actionType}`, {
                                method: "POST",
                                headers: {
                                    "Content-Type": "application/x-www-form-urlencoded",
                                },
                                body: `csrf_token=${csrfToken}`
                            })
                            .then(res => res.json())
                            .then(data => {
                                if (data.success) {
                                    window.location.reload();
                                    alert("Timesheet has been updated!");
                                } else {
                                    window.location.reload();
                                    alert(data.error || "Failed updated timesheet.");
                                }
                            })
                            .catch(err => {
                                console.error("Error approving timesheet:", err);
                            });
                        }
                    });
                });

